import{_ as s,o as n,a as p,b as l}from"./app.DAp7B6qI.js";const t="/ascendc.github.io/assets/capi_half_to_int32_conversion.CTuC7uSk.png",c="/ascendc.github.io/assets/capi_float_to_int16_conversion.BDeGcSnt.png",f=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Reg矢量计算","link":"/api/SIMD-API/c_api/reg_compute/reg_compute"},{"text":"关键特性说明","link":"/api/SIMD-API/c_api/reg_compute/key_features"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/reg_compute/key_features.md","filePath":"api/SIMD-API/c_api/reg_compute/key_features.md","outlineHeaders":[{"level":2,"title":"硬件循环（HardwareLoop）","slug":"硬件循环（HardwareLoop）","link":"#硬件循环（HardwareLoop）"},{"level":3,"title":"Hardware Loop编码规范","slug":"Hardware-Loop编码规范","link":"#Hardware-Loop编码规范"},{"level":2,"title":"指令双发优化","slug":"指令双发优化","link":"#指令双发优化"},{"level":3,"title":"指令双发","slug":"指令双发","link":"#指令双发"},{"level":3,"title":"合理拆分VF循环","slug":"合理拆分VF循环","link":"#合理拆分VF循环"},{"level":3,"title":"手动控制循环拆分","slug":"手动控制循环拆分","link":"#手动控制循环拆分"},{"level":2,"title":"VF融合","slug":"VF融合","link":"#VF融合"},{"level":2,"title":"数据搬运优化","slug":"数据搬运优化","link":"#数据搬运优化"},{"level":3,"title":"数据搬运启用分布模式","slug":"数据搬运启用分布模式","link":"#数据搬运启用分布模式"}],"lastUpdated":1789723795000}'),e={name:"api/SIMD-API/c_api/reg_compute/key_features.md"};function o(i,a,r,d,_,h){return n(),p("div",null,[...a[0]||(a[0]=[l('<div><article class="markdown-body"><h1>关键特性说明</h1><h2 id="硬件循环（HardwareLoop）">硬件循环（HardwareLoop）<a class="header-anchor" href="#硬件循环（HardwareLoop）">​</a></h2><p>Reg矢量计算架构中，Vector Function（VF）是实现高性能向量计算的核心载体。VF函数中可以包含最多四层嵌套循环，每层循环中还可以包含多个串行循环。VF循环对控制结构的支持有限，仅支持for循环和条件判断，不支持switch、do-while和while-do等其他控制结构。当VF函数中的循环满足Hardware Loop编码规范会被编译器优化为Hardware Loop，提升整体的编码性能，否则它的循环逻辑会由迭代变量和条件判断语句构成Software Loop，无法开启VF循环优化。</p><h3 id="Hardware-Loop编码规范">Hardware Loop编码规范<a class="header-anchor" href="#Hardware-Loop编码规范">​</a></h3><ul><li>Hardware Loop最多能支持的嵌套层数为4层；支持串行的Hardware Loop循环。</li><li>迭代变量类型<br>VF内所有Loop的迭代变量必须是uint16_t类型。</li><li>起始值与步长<br>循环起始值从0开始。<br>每次迭代的步长必须是递增1。</li><li>循环内不允许跳转指令，比如条件判断跳转，如if/else、三元运算符?:。<br>VF内if/else在Loop内会阻碍Hardware Loop的生成，编译器虽然会尽可能的做if/else消除优化，但是不做完全性保证。</li><li>一旦执行，循环计数/边界不允许被更改。</li><li>若要利用外层循环的计数作为循环边界，将外层循环计数器赋值给标量后作为内层循环边界。</li></ul><h2 id="指令双发优化">指令双发优化<a class="header-anchor" href="#指令双发优化">​</a></h2><p>Reg矢量计算接口指令单双发的情况请参考<a href="../../../appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary.html">Reg矢量计算接口指令单双发汇总</a>。</p><p>指令双发优化的性能优化详细内容请参考<a href="../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/dual_issue_optimization.html">算子实践参考-指令双发优化</a>。</p><h3 id="指令双发">指令双发<a class="header-anchor" href="#指令双发">​</a></h3><p>指令双发指的是处理器在同一个时钟周期内，能够同时发射两条指令到执行单元进行处理。</p><p>这种机制可以在不改变程序逻辑的前提下，提升处理器在单位时间内的指令处理效率，是实现指令级并行的重要基础之一。</p><h3 id="合理拆分VF循环">合理拆分VF循环<a class="header-anchor" href="#合理拆分VF循环">​</a></h3><p>VF并不是写的越长，把所有运算都放在一个for循环内就好，需要适当的搬出中间结果到Unified Buffer（UB），减少数据依赖。当指令数量过多，可能触发Icache Miss，即使循环间不存在依赖，也无法进行双发。当循环内包含同步，可以通过切分循环将同步外提减少同步次数。</p><h3 id="手动控制循环拆分">手动控制循环拆分<a class="header-anchor" href="#手动控制循环拆分">​</a></h3><p>如果循环内存在依赖关系过多的指令，指令无法并发执行，即无法启用双发特性。可以通过展开循环，提升指令双发能力，贴近硬件乱序执行的特性；减少指令因为寄存器资源未到位而产生的等待。</p><h2 id="VF融合">VF融合<a class="header-anchor" href="#VF融合">​</a></h2><p>VF融合是将代码中多个VF函数融合成一个VF函数，有效提升性能。VF融合特性是编译器优化特性，通过编译选项--cce-simd-vf-fusion=true开启，VF自动融合会借助Loop Fuse算法，将VF转换成Loop形态，然后将控制流等价（Control-Flow-Equivalent）的VF进行融合，最后将VF进行还原。编译器首先会做融合前的合法性检查，判断两个VF是否等价，Main侧中间代码是否能在VF内执行以及融合后是否可产生正收益。如果满足VF融合条件，编译器会自动执行VF融合优化，为保证融合后的VF执行逻辑与语义与融合前一致，会在原来两个VF之间保守地插入同步指令，编译器还会尝试外提、合并融合后的VF中的指令，对VF代码进行优化。融合策略是能融尽融，用户按照符合融合的合法性检查的模式进行编码，可以增加VF融合的机会。用户也可以参考融合原理手动进行融合优化。</p><p>VF融合的性能优化详细内容请参考<a href="../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/vf_fusion_optimization.html">算子实践参考-VF融合优化</a>。</p><h2 id="数据搬运优化">数据搬运优化<a class="header-anchor" href="#数据搬运优化">​</a></h2><p>Reg向量计算C API提供了下表所示多种搬运指令，合理选择搬运接口并利用接口能力进行优化。连续非对齐场景优化的性能优化详细内容请参考<a href="../../../../guide/operator_practice/simd_operator_optimization/vector_compute/vf_optimization/continuous_unaligned_optimization.html">算子实践参考-连续非对齐场景优化</a>。</p><table><thead><tr><th align="left">场景</th><th align="left">C API接口</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">连续对齐搬入</td><td align="left"><a href="./load/asc_loadalign.html">asc_loadalign</a></td><td align="left">从32字节对齐的UB起始地址连续搬入到向量数据寄存器或掩码寄存器。</td></tr><tr><td align="left">非连续对齐搬入</td><td align="left"><a href="./load/asc_loadalign.html">asc_loadalign</a></td><td align="left">从32字节对齐的UB起始地址非连续搬入多个DataBlock。</td></tr><tr><td align="left">连续非对齐搬入</td><td align="left"><a href="./load/asc_loadunalign.html">asc_loadunalign</a></td><td align="left">从非32字节对齐的UB起始地址连续搬入到向量数据寄存器。</td></tr><tr><td align="left">掩码寄存器搬入</td><td align="left"><a href="./load/asc_loadalign.html">asc_loadalign</a>、<a href="./load/asc_loadalign_mask.html">asc_loadalign_mask</a></td><td align="left">从UB连续搬入掩码寄存器。</td></tr><tr><td align="left">离散搬入</td><td align="left"><a href="./ub_gather/asc_gather.html">asc_gather</a></td><td align="left">根据索引值将UB中的元素收集到向量数据寄存器。</td></tr><tr><td align="left">DataBlock离散搬入</td><td align="left"><a href="./ub_gather/asc_gather_datablock.html">asc_gather_datablock</a></td><td align="left">根据索引值将UB中的元素按DataBlock（32B）收集到向量数据寄存器。</td></tr><tr><td align="left">连续对齐搬出</td><td align="left"><a href="./store/asc_storealign.html">asc_storealign</a></td><td align="left">将向量数据寄存器或掩码寄存器连续搬出到32字节对齐的UB地址。</td></tr><tr><td align="left">连续非对齐搬出</td><td align="left"><a href="./store/asc_storeunalign.html">asc_storeunalign</a></td><td align="left">将向量数据寄存器连续搬出到非32字节对齐的UB地址。</td></tr><tr><td align="left">离散搬出</td><td align="left"><a href="./scatter/asc_scatter.html">asc_scatter</a></td><td align="left">根据索引值将向量数据寄存器中的元素离散搬出到UB。</td></tr><tr><td align="left">寄存器间搬运</td><td align="left"><a href="./reg_copy/asc_copy.html">asc_copy</a></td><td align="left">支持向量数据寄存器复制到向量数据寄存器，掩码寄存器复制到掩码寄存器，向量数据寄存器复制到掩码寄存器三种模式。</td></tr></tbody></table><h3 id="数据搬运启用分布模式">数据搬运启用分布模式<a class="header-anchor" href="#数据搬运启用分布模式">​</a></h3><ul><li><p>连续对齐搬入</p><p>如图<a href="#fig1">half转int32_t类型转换过程</a>，将UB地址<code>x_addr</code>上数据量为VL/2的<code>half</code>类型元素通过<a href="./load/asc_loadalign_unpack.html">asc_loadalign_unpack</a>搬入<code>x_reg</code>，调用<a href="./reg_convert/asc_half2int32.html">asc_half2int32_rd</a>将<code>half</code>转换为<code>int32_t</code>并写入<code>y_reg</code>，最后通过<a href="./store/asc_storealign.html">asc_storealign</a>搬出至UB地址<code>y_addr</code>。</p><p><strong>图1</strong> half转int32_t类型转换过程<a id="fig1"></a></p><p><img src="'+t+`" alt title="half转int32_t类型转换过程"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">half_to_int32_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">y_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="w"> </span><span class="n">x_addr</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_half</span><span class="w"> </span><span class="n">x_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int32_t</span><span class="w"> </span><span class="n">y_reg</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>

<span class="w">    </span><span class="n">asc_loadalign_unpack</span><span class="p">(</span><span class="n">x_reg</span><span class="p">,</span><span class="w"> </span><span class="n">x_addr</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_half2int32_rd</span><span class="p">(</span><span class="n">y_reg</span><span class="p">,</span><span class="w"> </span><span class="n">x_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">ASC_POSITION_EVEN</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">y_addr</span><span class="p">,</span><span class="w"> </span><span class="n">y_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li><li><p>连续对齐搬出</p><p>如图<a href="#fig2">float转int16_t类型转换过程</a>，将UB地址<code>x_addr</code>上数据量为VL的<code>float</code>类型元素通过<a href="./load/asc_loadalign.html">asc_loadalign</a>搬入<code>x_reg</code>，调用<a href="./reg_convert/asc_float2int16.html">asc_float2int16_rn</a>将<code>float</code>转换为<code>int16_t</code>并写入<code>y_reg</code>，最后通过<a href="./store/asc_storealign_pack.html">asc_storealign_pack</a>搬出至UB地址<code>y_addr</code>。</p><p><strong>图2</strong> float转int16_t类型转换过程<a id="fig2"></a></p><p><img src="`+c+`" alt title="float转int16_t类型转换过程"></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">float_to_int16_vf</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">int16_t</span><span class="o">*</span><span class="w"> </span><span class="n">y_addr</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x_addr</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">vector_float</span><span class="w"> </span><span class="n">x_reg</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_int16_t</span><span class="w"> </span><span class="n">y_reg</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="w">    </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">count</span><span class="p">);</span>

<span class="w">    </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">x_reg</span><span class="p">,</span><span class="w"> </span><span class="n">x_addr</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_float2int16_rn</span><span class="p">(</span><span class="n">y_reg</span><span class="p">,</span><span class="w"> </span><span class="n">x_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">ASC_POSITION_EVEN</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_storealign_pack</span><span class="p">(</span><span class="n">y_addr</span><span class="p">,</span><span class="w"> </span><span class="n">y_reg</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></li></ul></article></div>`,1)])])}const u=s(e,[["render",o]]);export{f as __pageData,u as default};
